)

/** `combinedHours` is two measurement methods added together, not one metric. `note` says which. */
data class ChessBoardTime(
    val lichessHours: Int,
    val chesscomHours: Int,
    val combinedHours: Int,
    val chesscomGames: Int,
    val note: String,
)

/** Fractions, not percentages: multiply by 100 to print. */
data class ChessThesis(
    val decidedOnClock: Double,
    val lossesOnTime: Double,
    val winsOnTime: Double,
    val sampleSize: Int,
    val deciles: List<ChessDecile>,
)

/** Mean fraction of the starting clock still left. `bucket` is 0-based; the axis step is 100 / deciles.size. */
data class ChessDecile(
    val bucket: Int,
    val win: Double,
    val loss: Double,
    val gap: Double,
)

data class ChessDiscipline(
    val distinctDays: Int,
    val spanDays: Int,
    val longestDayStreak: Int,
    val longestWin: Int,
    val longestLoss: Int,
)

/** Win rate by how deep into one sitting the game was. `n` is thin at the tail and is rendered with it. */
data class ChessSessionGame(
    val position: Int,
    val winRate: Double,
    val n: Int,
)

data class ChessActivityYear(
    val year: String,
    val lichess: Int,
    val chesscom: Int,
)

data class ChessRepertoireYear(
    val year: String,
